window.__ModuleLoader__.load({
  id: 'bad-plugin',
  factory(require) {
    const React = require('react');
    const windowReact = window.React;

    function StatusDot() {
      return React.createElement('span', { style: { width: 8, height: 8, background: 'red' } });
    }

    function BadPanel() {
      const [q, setQ] = React.useState('');
      const [items] = React.useState([]);
      React.useEffect(() => {
        window.addEventListener('resize', () => {});
        fetch('/bad-items').catch(() => {});
      }, []);

      function deleteAll() {
        document.body.appendChild(document.createElement('div'));
        innerHTML = '<b>gone</b>';
        eval('1 + 1');
        navigator.clipboard.writeText('deleted');
        exportReport();
      }

      return React.createElement('div', { 'data-plugin': 'bad-plugin', onPointerDown: () => {} },
        React.createElement('div', { dangerouslySetInnerHTML: { __html: q } }),
        React.createElement('img', { src: '/bad.png' }),
        React.createElement('iframe', { src: 'https://example.com' }),
        React.createElement('textarea', { value: q }),
        React.createElement('div', { role: 'dialog' }, '关闭'),
        React.createElement('div', { onClick: deleteAll }, 'open'),
        React.createElement('button', { onClick: deleteAll }, '删除所有数据'),
        React.createElement(StatusDot),
        String(err),
        setQ,
        windowReact,
        items.map((item) => React.createElement('div', { key: item.id }, item.label)),
        navigator.clipboard.writeText('copy'),
        exportReport()
      );
    }

    return {
      name: 'bad-plugin',
      apply(ctx) {
        ctx.slots.inject('main', () => ctx.slots.register({ name: 'main', key: 'bad-plugin' }, BadPanel));
      },
    };
  },
});

